train = [20, 30, 25, 35, 22, 32, 27, 37]
test = [24, 34, 29, 39]
def mae(f):
    return sum(abs(a - p) for a, p in zip(test, f)) / len(test)
res = {
    'naive': mae([train[-1]] * 4),
    'moving average': mae([sum(train[-4:]) / 4] * 4),
    'seasonal naive': mae(train[-4:]),
}
for k, v in res.items():
    print(k + ': ' + str(round(v, 2)))
print('best: ' + min(res, key=res.get))
